export function topicForRule(id) {
  return Object.keys(topics).find(key => topics[key].rules?.some(rule => rule[0] === id));
}

export function logicText(key) {
  const topic = topics[key];
  const branches = (topic.rules ?? []).map(([id, condition, outcome, note], index) =>
    `${index ? 'ИНАЧЕ ЕСЛИ' : 'ЕСЛИ'} ${condition}:\n  ${outcome}${note ? '\n  // ' + note : ''}\n  // ${id}`);
  return [topic.name, topic.note, topic.code, ...branches].filter(Boolean).join('\n\n');
}
